put-patch.code:
# The stored task
{ "id": "42", "title": "Pack boxes", "done": false, "assignee": "ana" }

# PUT replaces everything. The assignee was left out, so it is gone.
PUT /tasks/42
{ "title": "Pack boxes", "done": true }
  ->  { "id": "42", "title": "Pack boxes", "done": true, "assignee": null }

# PATCH changes what it names and leaves the rest.
PATCH /tasks/42
{ "done": true }
  ->  { "id": "42", "title": "Pack boxes", "done": true, "assignee": "ana" }

patch-null.code:
# Change the title. The assignee is not mentioned, so it stays.
PATCH /tasks/42
{ "title": "Pack the boxes" }

# Remove the assignee. null means "no value".
PATCH /tasks/42
{ "assignee": null }

# Remove every label. An empty list is a value.
PATCH /tasks/42
{ "labels": [] }

